action.query:
query Query($where: LotManagementWhereInput, $orderBy: [LotManagementOrderByInput!], $first: Int, $after: String) {
  lotManagement(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        master
        fromLot
        expirationActionAt
        expirationAt
        holdUntilAt
        maturityAt
        originationAt
        retestAt
        status{id
    name}
        expirationActionId
      }
    }
  }
}
